/**
 * Une seule déclaration du chemin hors ligne pour le fichier généré, le
 * module de branding et le service worker.
 */
export const OFFLINE_PATH = '/offline.html';
export const MANIFEST_PATH = '/manifest.webmanifest';

function cachePrefix(branding: Branding): string {
	const slug = branding.shortName
		.toLowerCase()
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-+|-+$/g, '');
	return slug || 'app';
}

function buildAppShell(branding: Branding, palette: EmailPalette): string {
	return `<!doctype html>
<!-- Generated by scripts/generate.ts from config/branding.json and src/lib/ui/tokens.css. Do not edit. -->
<html lang="${branding.locale}" style="background-color: ${palette.paper}; color-scheme: light">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width, initial-scale=1, interactive-widget=resizes-content, viewport-fit=cover" />
		<meta name="text-scale" content="scale" />
		<meta name="color-scheme" content="light" />
		<meta name="apple-mobile-web-app-capable" content="yes" />
		<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
		%sveltekit.head%
	</head>
	<body data-sveltekit-preload-data="hover">
		<div style="display: contents">%sveltekit.body%</div>
	</body>
</html>
`;
}

function buildRobots(branding: Branding): string {
	const rule = branding.indexable ? 'Allow: /' : 'Disallow: /';
	return `# Generated by scripts/generate.ts from config/branding.json. Do not edit.
User-agent: *
${rule}
`;
}

function buildManifest(branding: Branding, icons: Record<IconRole, string>, palette: EmailPalette) {
	return `${JSON.stringify(
		{
			id: branding.startUrl,
			name: branding.name,
			short_name: branding.shortName,
			description: branding.description,
			lang: branding.locale,
			dir: branding.direction,
			start_url: branding.startUrl,
			scope: branding.scope,
			display: branding.display,
			background_color: palette.paper,
			theme_color: palette.ink,
			categories: branding.categories,
			icons: [
				{
					src: icons.icon192,
					sizes: `${branding.icons.icon192}x${branding.icons.icon192}`,
					type: 'image/png',
					purpose: 'any'
				},
				{
					src: icons.icon512,
					sizes: `${branding.icons.icon512}x${branding.icons.icon512}`,
					type: 'image/png',
					purpose: 'any'
				},
				{
					src: icons.maskable,
					sizes: `${branding.icons.maskable}x${branding.icons.maskable}`,
					type: 'image/png',
					purpose: 'maskable'
				}
			]
		},
		null,
		2
	)}\n`;
}

function buildBrandingModule(
	branding: Branding,
	icons: Record<IconRole, string>,
	palette: EmailPalette,
	authImage: string,
	textures: Record<TextureKey, string>
) {
	const value = {
		name: branding.name,
		shortName: branding.shortName,
		organisation: branding.organisation,
		description: branding.description,
		locale: branding.locale,
		timezone: branding.timezone,
		startUrl: branding.startUrl,
		scope: branding.scope,
		display: branding.display,
		indexable: branding.indexable,
		themeColor: palette.ink,
		backgroundColor: palette.paper,
		emailPalette: palette,
		socialImage: branding.socialImage,
		authImage,
		manifestPath: MANIFEST_PATH,
		offlinePath: OFFLINE_PATH,
		cachePrefix: cachePrefix(branding),
		icons,
		textures
	};

	return `${GENERATED_HEADER}export const branding = ${JSON.stringify(
		value,
		null,
		2
	)} as const;\n\nexport type Branding = typeof branding;\n`;
}

const SOCIAL_WIDTH = 1200;
const SOCIAL_HEIGHT = 630;
const SOCIAL_CREST = 184;
const AUTH_WIDTH = 1200;
const AUTH_HEIGHT = 800;
const TEXTURE_SIZE = 1024;

/**
 * Les sources sont photographiées; un gain linéaire ramène leur moyenne sur le
 * papier ou la glace du thème pour qu'une texture posée à pleine opacité ne
 * change pas la couleur de la surface.
 */
const TEXTURE_BRIGHTNESS: Record<TextureKey, number> = { paper: 1.06, ice: 1.08 };

async function renderTexture(
	root: string,
	sourcePath: string,
	brightness: number
): Promise<Buffer> {
	const source = await readFile(path.join(root, sourcePath));
	return sharp(source)
		.resize(TEXTURE_SIZE, TEXTURE_SIZE, { fit: 'cover', position: 'centre' })
		.linear(brightness)
		.webp({ quality: 78, effort: 6 })
		.toBuffer();
}

async function renderAuthImage(root: string, branding: Branding): Promise<Buffer> {
	const source = await readFile(path.join(root, branding.authSource));
	return sharp(source)
		.resize(AUTH_WIDTH, AUTH_HEIGHT, { fit: 'cover', position: 'centre' })
		.webp({ quality: 82, effort: 6 })
		.toBuffer();
}

function buildSocialOverlay(palette: EmailPalette): Buffer {
	return Buffer.from(
		`<svg xmlns="http://www.w3.org/2000/svg" width="${SOCIAL_WIDTH}" height="${SOCIAL_HEIGHT}" viewBox="0 0 ${SOCIAL_WIDTH} ${SOCIAL_HEIGHT}">
	<defs>
		<linearGradient id="side" x1="0" y1="0" x2="1" y2="0">
			<stop offset="0" stop-color="${palette.ink}" stop-opacity="0.95"/>
			<stop offset="0.46" stop-color="${palette.ink}" stop-opacity="0.86"/>
			<stop offset="0.68" stop-color="${palette.ink}" stop-opacity="0.42"/>
			<stop offset="1" stop-color="${palette.ink}" stop-opacity="0.12"/>
		</linearGradient>
		<linearGradient id="base" x1="0" y1="0" x2="0" y2="1">
			<stop offset="0" stop-color="${palette.ink}" stop-opacity="0"/>
			<stop offset="1" stop-color="${palette.ink}" stop-opacity="0.55"/>
		</linearGradient>
	</defs>
	<rect width="${SOCIAL_WIDTH}" height="${SOCIAL_HEIGHT}" fill="url(#side)"/>
	<rect y="${SOCIAL_HEIGHT - 150}" width="${SOCIAL_WIDTH}" height="150" fill="url(#base)"/>
	<rect x="64" y="56" width="${SOCIAL_CREST + 16}" height="${SOCIAL_CREST + 16}" rx="44" fill="${palette.paper}" fill-opacity="0.08"/>
	<rect y="${SOCIAL_HEIGHT - 8}" width="${SOCIAL_WIDTH}" height="8" fill="${palette.brand}"/>
</svg>`
	);
}

async function renderSocialImage(
	root: string,
	branding: Branding,
	svg: Buffer,
	palette: EmailPalette
): Promise<Buffer> {
	const source = await readFile(path.join(root, branding.socialSource));
	const background = await sharp(source)
		.resize(SOCIAL_WIDTH, SOCIAL_HEIGHT, { fit: 'cover', position: 'centre' })
		.toBuffer();
	const crest = await sharp(svg)
		.resize(SOCIAL_CREST, SOCIAL_CREST)
		.png()
		.toBuffer();

	return sharp(background)
		.composite([
			{ input: buildSocialOverlay(palette), top: 0, left: 0 },
			{ input: crest, top: 64, left: 72 }
		])
		.jpeg({ quality: 88, mozjpeg: true })
		.toBuffer();
}

export async function generateBranding(root: string): Promise<GeneratedFile[]> {
	const raw = JSON.parse(
		await readFile(path.join(root, 'config/branding.json'), 'utf8')
	);
	const branding = brandingSchema.parse(raw);
	const appPalette = parsePalette(
		await readFile(path.join(root, 'src/lib/ui/tokens.css'), 'utf8')
	);
	const palette = emailPaletteFrom(appPalette);
	const svg = await readFile(path.join(root, branding.iconSource));

	const icons = {} as Record<IconRole, string>;
	const files: GeneratedFile[] = [];

	for (const { role, slug, sizeKey } of ICON_ROLES) {
		const size = branding.icons[sizeKey];
		const contents = await renderIcon(svg, branding, palette, size, role === 'maskable');
		const digest = sha256(contents).slice(0, 12);
		const publicPath = `/icons/${slug}-${size}.${digest}.png`;
		icons[role] = publicPath;
		files.push({ path: `static${publicPath}`, contents });
	}

	const manifest = buildManifest(branding, icons, palette);
	files.push({ path: `static${MANIFEST_PATH}`, contents: manifest });

	files.push({ path: 'src/app.html', contents: buildAppShell(branding, palette) });
	files.push({ path: 'static/robots.txt', contents: buildRobots(branding) });
	files.push({
		path: `static${OFFLINE_PATH}`,
		contents: buildOfflinePage(branding, appPalette)
	});

	const auth = await renderAuthImage(root, branding);
	const authImage = `/auth/dressing-room-${sha256(auth).slice(0, 12)}.webp`;
	files.push({ path: `static${authImage}`, contents: auth });

	const textures = {} as Record<TextureKey, string>;
	for (const key of TEXTURE_KEYS) {
		const contents = await renderTexture(
			root,
			branding.textures[key],
			TEXTURE_BRIGHTNESS[key]
		);
		const publicPath = `/textures/${key}-${sha256(contents).slice(0, 12)}.webp`;
		textures[key] = publicPath;
		files.push({ path: `static${publicPath}`, contents });
	}

	const moduleSource = buildBrandingModule(branding, icons, palette, authImage, textures);
	files.push({ path: 'src/lib/generated/branding.ts', contents: moduleSource });

	const social = await renderSocialImage(root, branding, svg, palette);
	files.push({ path: `static${branding.socialImage}`, contents: social });

	const checksums = {
		generatedBy: 'scripts/generate.ts',
		source: 'config/branding.json, config/i18n/fr.ts and src/lib/ui/tokens.css',
		files: Object.fromEntries(
			files.map((file) => [file.path, sha256(file.contents)])
		)
	};
	files.push({
		path: 'static/generated-assets.json',
		contents: `${JSON.stringify(checksums, null, 2)}\n`
	});

	return files;
}

export async function writeGeneratedFiles(
	root: string,
	files: GeneratedFile[]
): Promise<void> {
	for (const file of files) {
		const target = path.join(root, file.path);
		await mkdir(path.dirname(target), { recursive: true });
		await writeFile(target, file.contents);
	}

	// Les icônes, la photo de connexion et les textures sont nommées par
	// contenu : une régénération laisse sinon des fichiers orphelins que le
	// service worker précacherait pour rien.
	const expected = new Set(files.map((file) => file.path.split(path.sep).join('/')));
	for (const dir of ['static/icons', 'static/auth', 'static/textures']) {
		for (const name of await readdir(path.join(root, dir)).catch(() => [])) {
			const relative = `${dir}/${name}`;
			if (!expected.has(relative)) {
				await unlink(path.join(root, dir, name));
			}
		}
	}
}

export function checksumOf(contents: Buffer | string): string {
	return sha256(contents);
}
